function ratio(a: string, b: string): number {
  const matched = (alo: number, ahi: number, blo: number, bhi: number): number => {
    let best = 0, bi = alo, bj = blo;
    for (let i = alo; i < ahi; i++) {
      for (let j = blo; j < bhi; j++) {
        let k = 0;
        while (i + k < ahi && j + k < bhi && a[i + k] === b[j + k]) k++;
        if (k > best) { best = k; bi = i; bj = j; }
      }
    }
    return best === 0 ? 0 : best + matched(alo, bi, blo, bj) + matched(bi + best, ahi, bj + best, bhi);
  };
  return a.length + b.length === 0 ? 1 : (2 * matched(0, a.length, 0, b.length)) / (a.length + b.length);
}

// 받아쓰기가 틀려도 메뉴판에서 가장 닮은 메뉴 찾기. cut보다 덜 닮았으면 '모름'(null)
function closestMenu(text: string, cut = 0.75): string | null {
  const t = text.replace(/[ .,?!]/g, "");
  let best = 0, bestName: string | null = null;
  for (const [name, m] of Object.entries(MENU)) {
    for (const a of m.alias) {
      if (a.length < 4) continue; // 짧은 별명은 우연히 닮기 쉬워 뺌
      for (const L of [a.length - 1, a.length, a.length + 1]) {
        for (let i = 0; i < Math.max(t.length - L + 1, 1); i++) {
          const r = ratio(a, t.slice(i, i + L));
          if (r > best) { best = r; bestName = name; }
        }
      }
    }
  }
  return best >= cut ? bestName : null;
}

// 긴 별명이 그대로 있으면 그것 → 닮은 것 → 짧은 별명 순
function findMenu(text: string): string | null {
  const t = squeeze(text);
  const longHit = Object.entries(MENU).find(([, m]) => m.alias.some((a) => a.length >= 4 && t.includes(a)));
  return (longHit ? longHit[0] : null) ?? closestMenu(text) ?? exactMenu(text);
}

// '두 잔' · '2개' · '하나' 같은 수량. 단위(잔·개·조각)를 꼭 본다('따뜻한'의 '한'에 속지 않게). 없으면 1
function findQty(text: string): number {
  const t = squeeze(text);
  const m = t.match(/(\d+|한|두|세|네|다섯|여섯|일곱|여덟|아홉|열)(잔|개|조각)/);
  if (m) return /^\d+$/.test(m[1]) ? Number(m[1]) : NUM[m[1]];
  const n = t.match(/하나|둘|셋|넷/);
  return n ? NUM[n[0]] : 1;
}

// 한 메뉴의 주문을 슬롯으로. temp: '-'는 해당 없음(디저트), null은 '아직 모름'(음료인데 말하지 않음)
function parseItem(text: string): Item | null {
  const menu = findMenu(text);
  if (menu === null) return null;
  const t = squeeze(text);
  const drink = MENU[menu].kind === "음료";
  let temp: string | null;
  if (!drink) temp = "-";
  else if (has(t, ["아이스", "차가운", "시원한"])) temp = "아이스";
  else if (has(t, ["따뜻", "뜨거운", "핫"])) temp = "따뜻하게";
  else temp = null;
  const size = drink && has(t, ["큰", "라지"]) ? "큰 컵" : "보통";
  return { menu, qty: findQty(text), temp, size };
}

// 도전 A: 한 문장에 여러 메뉴 ('A랑 B하고 C')
function parseItems(text: string): Item[] {
  const out: Item[] = [];
  for (const part of squeeze(text).replace(/,/g, "").split(/이랑|랑|하고|그리고/)) {
    const it = parseItem(part);
    if (it) out.push(it);
  }
  return out;
}

// 주문서를 보고 빠진 것 가운데 가장 앞의 것을 고른다(대화의 지휘자)
function nextSlot(order: Order): string {
  if (order.items.length === 0) return "menu";
  if (order.items.some((it) => it.temp === null)) return "temp";
  if (!order.done) return "more";
  if (order.where === null) return "where";
  return "confirm";
}

const TEXTS = ["아이스아메리카노두잔주세요.", "따뜻한 카페라떼 한 잔이요", "바닐라라떼큰걸로하나주세요.", "초코쿠키 2개주세요", "유자차 세 잔", "포장이요"];
const WANT: (Item | null)[] = [
  { menu: "아메리카노", qty: 2, temp: "아이스", size: "보통" },
  { menu: "카페라떼", qty: 1, temp: "따뜻하게", size: "보통" },
  { menu: "바닐라라떼", qty: 1, temp: null, size: "큰 컵" },
  { menu: "초코쿠키", qty: 2, temp: "-", size: "보통" },
  { menu: "유자차", qty: 3, temp: null, size: "보통" },
  null,
];
const got = TEXTS.map(parseItem);
TEXTS.forEach((t, i) => console.log(`${t} → ${JSON.stringify(got[i])}`));
check(got.length === 6 && same(got, WANT), "디저트는 temp '-', 음료인데 말하지 않으면 null('아직 모름')이어야 해요.");

// 주문서를 보고 다음에 물을 칸: 빠진 것 가운데 가장 앞의 것
const order: Order = { items: [], where: null, done: false };
const steps = [nextSlot(order)]; // 비어 있음 → menu
order.items.push(parseItem("아이스아메리카노두잔")!, parseItem("카페라떼하나")!);
steps.push(nextSlot(order)); // 라떼의 온도를 말하지 않음 → temp
order.items[1].temp = "따뜻하게";
steps.push(nextSlot(order)); // 더 주문할 것을 아직 안 물음 → more
order.done = true;
steps.push(nextSlot(order)); // → where
order.where = "포장";
steps.push(nextSlot(order)); // → confirm
console.log("다음에 물을 것:", steps.join(" → "));
check(same(steps, ["menu", "temp", "more", "where", "confirm"]), "주문서 상태에 따라 menu → temp → more → where → confirm 순이어야 해요.");
check(nextSlot({ items: [order.items[0]], where: "포장", done: true }) === "confirm" && nextSlot({ items: [], where: "포장", done: true }) === "menu",
  "포장을 먼저 말해도 메뉴가 비어 있으면 메뉴부터 물어야 해요(빠진 것 가운데 가장 앞의 것).");

talk.typescript:
// D45 · Part 2 · 대화의 흐름 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d45_talk.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 합성은 쓰지 않음)
//   글자로 하는 대화 시험: 손님의 말(받아쓰기 모양 그대로, 띄어쓰기 없이)을 한 턴씩 넣으면 주문서를 고치고 다음 질문을 돌려준다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}
const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // 값 전체가 같은지 (모양과 순서까지)

type Item = { menu: string; qty: number; temp: string | null; size: string };
type Order = { items: Item[]; where: string | null; done: boolean; fail?: number; state?: string };

// 메뉴판 (가상). alias = 손님이 부르는 다른 이름 + 받아쓰기가 자주 틀리는 표기
const MENU: Record<string, { price: number; kind: string; alias: string[] }> = {
  "아메리카노": { price: 3000, kind: "음료", alias: ["아메리카노"] },
  "카페라떼": { price: 3500, kind: "음료", alias: ["카페라떼", "카페라테", "라떼", "라테"] },
  "바닐라라떼": { price: 4000, kind: "음료", alias: ["바닐라라떼", "바닐라라테"] },
  "녹차라떼": { price: 4000, kind: "음료", alias: ["녹차라떼", "녹차라테"] },
  "유자차": { price: 3500, kind: "음료", alias: ["유자차"] },
  "초코쿠키": { price: 2000, kind: "디저트", alias: ["초코쿠키"] },
  "치즈케이크": { price: 4500, kind: "디저트", alias: ["치즈케이크", "치즈케익"] },
};
const BIG = 500; // 큰 컵은 500원 더
const NUM: Record<string, number> = { "한": 1, "두": 2, "세": 3, "네": 4, "다섯": 5, "여섯": 6, "일곱": 7, "여덟": 8, "아홉": 9, "열": 10, "하나": 1, "둘": 2, "셋": 3, "넷": 4 };
const squeeze = (s: string): string => s.replace(/ /g, "");
const has = (t: string, words: string[]): boolean => words.some((w) => t.includes(w));

// 별명이 글 안에 그대로 있으면 그 메뉴. 긴 별명부터 찾아야 '바닐라라떼'가 '카페라떼'로 잘못 알려지지 않는다.
function exactMenu(text: string): string | null {
  const t = squeeze(text);
  const pairs = Object.entries(MENU).flatMap(([name, m]) => m.alias.map((a): [string, string] => [a, name])).sort((p, q) => q[0].length - p[0].length);
  for (const [alias, name] of pairs) if (t.includes(alias)) return name;
  return null;
}

// 두 글이 얼마나 닮았나 (0 ~ 1): 가장 긴 공통 조각을 찾고 양옆을 되풀이해 센다 (Python difflib.SequenceMatcher.ratio와 같은 방식)
function ratio(a: string, b: string): number {
  const matched = (alo: number, ahi: number, blo: number, bhi: number): number => {
    let best = 0, bi = alo, bj = blo;
    for (let i = alo; i < ahi; i++) {
      for (let j = blo; j < bhi; j++) {
        let k = 0;
        while (i + k < ahi && j + k < bhi && a[i + k] === b[j + k]) k++;
        if (k > best) { best = k; bi = i; bj = j; }
      }
    }
    return best === 0 ? 0 : best + matched(alo, bi, blo, bj) + matched(bi + best, ahi, bj + best, bhi);
  };
  return a.length + b.length === 0 ? 1 : (2 * matched(0, a.length, 0, b.length)) / (a.length + b.length);
}

// 받아쓰기가 틀려도 메뉴판에서 가장 닮은 메뉴 찾기. cut보다 덜 닮았으면 '모름'(null)
function closestMenu(text: string, cut = 0.75): string | null {
  const t = text.replace(/[ .,?!]/g, "");
  let best = 0, bestName: string | null = null;
  for (const [name, m] of Object.entries(MENU)) {
    for (const a of m.alias) {
      if (a.length < 4) continue; // 짧은 별명은 우연히 닮기 쉬워 뺌
      for (const L of [a.length - 1, a.length, a.length + 1]) {
        for (let i = 0; i < Math.max(t.length - L + 1, 1); i++) {
          const r = ratio(a, t.slice(i, i + L));
          if (r > best) { best = r; bestName = name; }
        }
      }
    }
  }
  return best >= cut ? bestName : null;
}

// 긴 별명이 그대로 있으면 그것 → 닮은 것 → 짧은 별명 순
function findMenu(text: string): string | null {
  const t = squeeze(text);
  const longHit = Object.entries(MENU).find(([, m]) => m.alias.some((a) => a.length >= 4 && t.includes(a)));
  return (longHit ? longHit[0] : null) ?? closestMenu(text) ?? exactMenu(text);
}

// '두 잔' · '2개' · '하나' 같은 수량. 단위(잔·개·조각)를 꼭 본다('따뜻한'의 '한'에 속지 않게). 없으면 1
function findQty(text: string): number {
  const t = squeeze(text);
  const m = t.match(/(\d+|한|두|세|네|다섯|여섯|일곱|여덟|아홉|열)(잔|개|조각)/);
  if (m) return /^\d+$/.test(m[1]) ? Number(m[1]) : NUM[m[1]];
  const n = t.match(/하나|둘|셋|넷/);
  return n ? NUM[n[0]] : 1;
}

// 한 메뉴의 주문을 슬롯으로. temp: '-'는 해당 없음(디저트), null은 '아직 모름'(음료인데 말하지 않음)
function parseItem(text: string): Item | null {
  const menu = findMenu(text);
  if (menu === null) return null;
  const t = squeeze(text);
  const drink = MENU[menu].kind === "음료";
  let temp: string | null;
  if (!drink) temp = "-";
  else if (has(t, ["아이스", "차가운", "시원한"])) temp = "아이스";
  else if (has(t, ["따뜻", "뜨거운", "핫"])) temp = "따뜻하게";
  else temp = null;
  const size = drink && has(t, ["큰", "라지"]) ? "큰 컵" : "보통";
  return { menu, qty: findQty(text), temp, size };
}

// 도전 A: 한 문장에 여러 메뉴 ('A랑 B하고 C')
function parseItems(text: string): Item[] {
  const out: Item[] = [];
  for (const part of squeeze(text).replace(/,/g, "").split(/이랑|랑|하고|그리고/)) {
    const it = parseItem(part);
    if (it) out.push(it);
  }
  return out;
}

// 주문서를 보고 빠진 것 가운데 가장 앞의 것을 고른다(대화의 지휘자)
function nextSlot(order: Order): string {
  if (order.items.length === 0) return "menu";
  if (order.items.some((it) => it.temp === null)) return "temp";
  if (!order.done) return "more";
  if (order.where === null) return "where";
  return "confirm";
}

// 연달아 못 알아들은 횟수(1부터) → [할 말, 직원을 부를지]. 매번 다르게 묻고, 세 번째에는 사람을 부른다
function reask(nFail: number): [string, boolean] {
  if (nFail <= 1) return ["죄송합니다. 다시 한번 말씀해 주세요.", false];
  if (nFail === 2) return ["잘 알아듣지 못했습니다. 아메리카노 한 잔처럼 메뉴와 수량을 말씀해 주세요.", false];
  return ["직원을 불러 드리겠습니다. 잠시만 기다려 주세요.", true];
}

// 말로 주문 고치기: 빼/취소/삭제 → 그 메뉴를 지움, 바꿔/변경/으로 → 수량을 바꿈. 고쳤으면 true
function applyEdit(order: Order, text: string): boolean {
  const menu = findMenu(text);
  const t = squeeze(text);
  const hit = order.items.filter((it) => it.menu === menu);
  if (hit.length === 0) return false;
  if (has(t, ["빼", "취소", "삭제"])) {
    order.items = order.items.filter((it) => it.menu !== menu);
    return true;
  }
  if (has(t, ["바꿔", "변경", "으로"])) {
    const q = findQty(text);
    if (q < 1) return false; // 0잔으로는 바꾸지 않음
    hit[0].qty = q;
    return true;
  }
  return false;
}

type Row = Item & { price: number; sum: number };
// 주문서: 한 개 값(price)과 줄 합계(sum), 전체 합계(total)는 코드가 계산한다(정수 원)
function receipt(order: Order): { items: Row[]; where: string | null; total: number } {
  const rows = order.items.map((it) => {
    const price = MENU[it.menu].price + (it.size === "큰 컵" ? BIG : 0);
    return { ...it, price, sum: price * it.qty };
  });
  return { items: rows, where: order.where, total: rows.reduce((s, r) => s + r.sum, 0) };
}

const ASK: Record<string, string> = {
  menu: "주문하실 메뉴를 말씀해 주세요.", temp: "{menu}는 따뜻하게 드릴까요, 아이스로 드릴까요?",
  more: "더 주문하실 것이 있으신가요?", where: "드시고 가시나요, 포장하시나요?",
};
const YES = ["네", "예", "맞", "응"];
const NO = ["아니", "없", "됐", "그게다", "다예요", "다에요", "괜찮"];
const WHERE: Record<string, string[]> = { "포장": ["포장", "가져", "테이크"], "매장": ["매장", "먹고", "여기"] };
const COUNT = ["", "한", "두", "세", "네", "다섯", "여섯", "일곱", "여덟", "아홉", "열"];

const newOrder = (): Order => ({ items: [], where: null, done: false, fail: 0, state: "주문 중" });

const DIGITS = "영일이삼사오육칠팔구";

function koUnder10000(num: number): string {
  let out = "";
  let n = num;
  for (const [unit, val] of [["천", 1000], ["백", 100], ["십", 10]] as [string, number][]) {
    const q = Math.floor(n / val);
    n %= val;
    if (q) out += (q === 1 ? "" : DIGITS[q]) + unit;
  }
  return out + (n ? DIGITS[n] : "");
}

// 13500 → '만삼천오백 원', 102000 → '십만이천 원' (합성기가 숫자를 엉뚱하게 읽지 않게 글자로). 1억 이상은 숫자 그대로
function koMoney(n: number): string {
  if (n >= 100_000_000) return `${n.toLocaleString("en-US")} 원`;
  const man = Math.floor(n / 10000);
  const out = (man ? (man === 1 ? "" : koUnder10000(man)) + "만" : "") + koUnder10000(n % 10000);
  return (out || "영") + " 원";
}

// 한 줄을 읽기 좋게: '아이스 아메리카노 큰 컵 두 잔'
function itemText(it: Item): string {
  const unit = MENU[it.menu].kind === "음료" ? "잔" : "개";
  const n = it.qty <= 10 ? COUNT[it.qty] : String(it.qty);
  const words = [it.temp === "아이스" ? "아이스" : it.temp === "따뜻하게" ? "따뜻한" : "", it.menu, it.size === "큰 컵" ? "큰 컵" : ""];
  return `${words.filter((w) => w).join(" ")} ${n} ${unit}`;
}

// 읽어 주며 확인 (명시적 확인)
function confirmText(order: Order): string {
  return `주문 확인하겠습니다. ${order.items.map(itemText).join(", ")}. ${order.where}, 모두 ${koMoney(receipt(order).total)}입니다. 맞으신가요?`;
}

// 같은 메뉴 · 온도 · 크기면 수량을 더함
function addItems(order: Order, items: Item[]): void {
  for (const it of items) {
    const found = order.items.find((o) => o.menu === it.menu && o.temp === it.temp && o.size === it.size);
    if (found) found.qty += it.qty;
    else order.items.push(it);
  }
  order.done = false;
}

// 대화 한 턴: 받아쓴 글로 주문서를 고치고(수정 → 메뉴 담기 → 온도 → 포장 → 아니요/네), 다음에 할 말을 돌려줌
function kioskTurn(order: Order, text: string): string {
  const t = squeeze(text);
  let slot = nextSlot(order);
  let hit = false;
  const temp = has(t, ["아이스", "차가운", "시원한"]) ? "아이스" : has(t, ["따뜻", "뜨거운", "핫"]) ? "따뜻하게" : null;
  const where = Object.keys(WHERE).find((k) => has(t, WHERE[k])) ?? null;
  if (order.items.length > 0 && applyEdit(order, text)) {
    hit = true; // ① 수정은 어느 단계에서든 먼저 받음
  } else {
    const removal = has(t, ["빼", "취소", "삭제"]);
    const items = removal ? [] : parseItems(text); // 지우라는 말인데 지울 메뉴가 없으면(위 수정이 실패) 새로 담지 않고 되묻는다
    if (parseItems(text).some((it) => it.qty < 1) && !removal) return "수량을 다시 말씀해 주세요. 한 잔 이상으로 말씀해 주세요."; // 0잔 · 0개는 담지 않고 수량을 되묻는다
    if (items.length > 0) {
      addItems(order, items); // ② 메뉴가 들어 있으면 담음
      hit = true;
    } else if (slot === "temp" && temp) {
      order.items.find((it) => it.temp === null)!.temp = temp;
      hit = true;
    }
    if (where && order.items.length > 0) { // ③ 포장 여부는 묻기 전에 말해도 받음
      order.where = where;
      hit = true;
      if (slot === "more" && items.length === 0) order.done = true; // "더 있으신가요?"에 "포장이요"라고 답했으면 더 없다는 뜻
    }
    if (!hit && slot === "more" && has(t, NO)) {
      order.done = true;
      hit = true;
    }
    if (!hit && slot === "confirm" && has(t, NO)) {
      order.fail = 0;
      return "수정할 내용을 말씀해 주세요. 예를 들면, 라떼 빼 주세요.";
    }
    if (!hit && slot === "confirm" && has(t, YES)) {
      order.state = "완료";
      return `주문이 접수되었습니다. 모두 ${koMoney(receipt(order).total)}입니다. 카드를 꽂아 주세요.`;
    }
  }
  if (!hit) { // ④ 못 알아들었으면 되묻기
    order.fail = (order.fail ?? 0) + 1;
    const [msg, callStaff] = reask(order.fail);
    if (callStaff) order.state = "직원 호출";
    return msg;
  }
  order.fail = 0;
  slot = nextSlot(order); // ⑤ 고친 주문서를 보고 다음에 물을 것을 고름
  if (slot === "confirm") return confirmText(order);
  return ASK[slot].replace("{menu}", order.items.find((it) => it.temp === null)?.menu ?? "");
}

// 글자로 하는 대화 시험: 손님의 말들을 차례로 넣어 봄
function talk(lines: string[], show = true): Order {
  const order = newOrder();
  if (show) console.log(`  키오스크: ${ASK.menu}`);
  for (const line of lines) {
    const reply = kioskTurn(order, line);
    if (show) console.log(`  손님: ${line}\n  키오스크: ${reply}`);
    if (order.state !== "주문 중") break;
  }
  return order;
}

console.log("첫째 대화");
const o1 = talk(["아이스아메리카노두잔주세요.", "라떼도하나요.", "따뜻하게주세요.", "더없어요.", "가져갈게요.", "네맞아요."]);
const o2 = talk(["따뜻한 유자차 한 잔 포장이요.", "없어요.", "네."], false); // 한 문장에 메뉴 · 온도 · 수량 · 포장이 다 들어 있음
const o3 = talk(["날씨가좋네요", "음", "그러게요"], false); // 메뉴와 상관없는 말만
console.log("둘째 대화:", o2.items.map(itemText), o2.where, o2.state, "· 셋째 대화:", o3.state);
check(o1.state === "완료" && receipt(o1).total === 9500, "첫 대화는 아이스 아메리카노 2잔 + 카페라떼 1잔 = 9,500원으로 끝나야 해요.");
check(o2.state === "완료" && o2.where === "포장", "포장을 먼저 말하면 다시 묻지 않아야 해요.");
check(o3.state === "직원 호출" && o3.fail === 3, "세 번 못 알아들으면 직원을 불러야 해요(끝없이 되묻지 않기).");

// 예외 대화: 없는 메뉴를 빼 달라고 하면 장바구니는 그대로 두고 되묻는다
const o4 = newOrder();
kioskTurn(o4, "아이스아메리카노한잔주세요.");
const r4 = kioskTurn(o4, "유자차빼주세요.");
console.log("없는 메뉴 빼기:", r4, o4.items.map((i) => i.menu));
check(same(o4.items.map((i) => i.menu), ["아메리카노"]) && r4 === reask(1)[0] && o4.fail === 1, "주문에 없는 메뉴를 빼 달라고 하면 새로 담지 말고 장바구니를 그대로 두고 되물어야 해요.");
// 수량 0: 담지 않고 수량을 되묻는다
const o5 = newOrder();
const r5 = kioskTurn(o5, "아메리카노0잔주세요.");
console.log("수량 0:", r5);
check(o5.items.length === 0 && r5.startsWith("수량을 다시"), "0잔은 담지 않고 수량을 되물어야 해요.");
kioskTurn(o5, "아메리카노한잔주세요.");
check(same(o5.items.map((i) => i.menu), ["아메리카노"]) && o5.items[0].qty === 1, "수량을 다시 말하면 정상으로 담겨야 해요.");
// 큰 금액 읽기: 만 단위 앞이 두 자리(십만 · 삼십사만 …)여도 읽어야 함
const o6 = talk(["아이스아메리카노34잔주세요.", "더없어요.", "포장이요."], false);
const amounts = [0, 9999, 10000, 13500, 99999, 100000, 102000, 1234567];
const money = amounts.map(koMoney);
console.log("금액 읽기:", money);
check(receipt(o6).total === 102000 && confirmText(o6).includes("십만이천 원"), "아메리카노 34잔(102,000원)은 '십만이천 원'으로 읽어야 해요.");
check(same(money, ["영 원", "구천구백구십구 원", "만 원", "만삼천오백 원", "구만구천구백구십구 원", "십만 원", "십만이천 원", "백이십삼만사천오백육십칠 원"]),
  "10,000원 · 99,999원 · 100,000원 경계의 금액 읽기가 모두 맞아야 해요.");

noise.typescript:
// D45 · Part 3 · 매장 소음과 말 끝 찾기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d45_noise.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 합성은 쓰지 않음)
//   소음 바닥에 맞춰 말 끝 문턱을 올리는 Endpointer를, 고정 문턱(-38 dB)과 견준다(합성한 손님 말 3번 + 매장 소음 · 소음이 클수록 고정 문턱은 말 끝을 놓침)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}
const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // 값 전체가 같은지 (모양과 순서까지)

const SR = 16000;
const FRAME = SR / 50; // 20 ms 조각 = 320 샘플

// 아래에서 q% 자리의 값 (numpy.percentile의 기본 방식: 이웃한 두 값 사이를 직선으로)
function percentile(xs: number[], q: number): number {
  const s = [...xs].sort((a, b) => a - b);
  const pos = ((s.length - 1) * q) / 100;
  const lo = Math.floor(pos);
  const hi = Math.min(lo + 1, s.length - 1);
  return s[lo] + (s[hi] - s[lo]) * (pos - lo);
}

// 소음에 맞춘 문턱 = 소음 바닥(아래에서 10% 자리) + margin. 평균이 아니라 10% 자리를 쓰는 까닭: 손님의 말이 섞여도 바닥이 오르지 않게
function speechThreshold(dbHistory: number[], margin = 8.0, lowest = -50.0): number {
  if (dbHistory.length === 0) return lowest + margin;
  return Math.max(percentile(dbHistory, 10), lowest) + margin;
}

const HANG_SEC = 0.7; // 말 끝으로 보는 조용함(초)
const MIN_SPEECH = 0.25; // 너무 짧은 소리 무시
const START_FRAMES = 3; // 3조각 이어져야 말의 시작

// 같은 숫자가 나오는 난수(mulberry32) — 실행할 때마다 같은 합성 소리
function makeRng(seed: number): { next: () => number; gauss: () => number } {
  let s = seed >>> 0;
  const next = (): number => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  return { next, gauss: () => Math.sqrt(-2 * Math.log(1 - next())) * Math.cos(2 * Math.PI * next()) };
}

// 손님의 말을 흉내 낸 합성 소리: 180 Hz와 배음, 음절처럼 4 Hz로 커졌다 작아짐 (진짜 합성기 대신)
function speechBurst(sec: number): number[] {
  const out: number[] = [];
  const n = Math.floor(sec * SR);
  for (let i = 0; i < n; i++) {
    const t = i / SR;
    const env = 0.75 + 0.25 * Math.sin(2 * Math.PI * 4 * t);
    out.push(env * 0.14 * (Math.sin(2 * Math.PI * 180 * t) + 0.5 * Math.sin(2 * Math.PI * 360 * t) + 0.3 * Math.sin(2 * Math.PI * 540 * t)));
  }
  return out;
}

const rms = (x: number[]): number => Math.sqrt(x.reduce((s, v) => s + v * v, 0) / x.length);

// 조용한 앞 구간 → (말 → 조용함) × nSpeech. 돌려주는 값: [소리, 말 부분만의 rms]
function makeStream(nSpeech = 3, lead = 1.5, gap = 2.0, say = 1.2): [number[], number] {
  const y: number[] = new Array(Math.floor(lead * SR)).fill(0);
  const voiced: number[] = [];
  for (let k = 0; k < nSpeech; k++) {
    const s = speechBurst(say);
    for (const v of s) { voiced.push(v); y.push(v); }
    for (let i = 0; i < Math.floor(gap * SR); i++) y.push(0);
  }
  return [y, rms(voiced)];
}

// 매장 소음(웅웅 120 Hz + 쉬익)을 말의 크기 기준 SNR(dB)로 섞는다. snr이 null이면 조용한 매장
function addStoreNoise(y: number[], speechRms: number, snr: number | null): number[] {
  if (snr === null) return y;
  const rng = makeRng(11);
  const raw = y.map((_, i) => 0.5 * Math.sin((2 * Math.PI * 120 * i) / SR) + rng.gauss());
  const k = speechRms / 10 ** (snr / 20) / rms(raw);
  return y.map((v, i) => v + raw[i] * k);
}

// 20 ms 조각을 받아 말이 끝나면 [끝난 시각, 말의 길이(초)]를 돌려줌. adaptive=false면 고정 문턱 -38 dB
class Endpointer {
  adaptive: boolean;
  t = 0;
  inSpeech = false;
  quiet = 0;
  loud = 0;
  n = 0;
  pre = 0;
  hist: number[] = [];
  constructor(adaptive = true) {
    this.adaptive = adaptive;
  }
  feed(x: number[]): [number, number] | null {
    const db = 20 * Math.log10(rms(x) + 1e-9);
    let out: [number, number] | null = null;
    const th = this.adaptive ? speechThreshold(this.hist.slice(-150)) : -38.0; // 최근 3초의 크기로 문턱을 정함
    if (!this.inSpeech) {
      this.hist.push(db); // 말이 아닐 때만 소음 기록에 넣음
      this.pre = Math.min(this.pre + 1, 15); // 직전 0.3초는 남겨 둠
      this.loud = db > th ? this.loud + 1 : 0;
      if (this.loud >= START_FRAMES) {
        this.inSpeech = true;
        this.quiet = 0;
        this.n = this.pre;
      }
    } else {
      this.n += 1;
      this.quiet = db <= th ? this.quiet + x.length / SR : 0;
      if (this.quiet >= HANG_SEC) { // 조용함이 이어지면 말 끝
        this.inSpeech = false;
        this.loud = 0;
        const length = (this.n * FRAME) / SR;
        if (length - HANG_SEC >= MIN_SPEECH) out = [this.t + x.length / SR - HANG_SEC, length];
      }
    }
    this.t += x.length / SR;
    return out;
  }
}

function findEnds(y: number[], adaptive: boolean): [number, number][] {
  const ep = new Endpointer(adaptive);
  const ends: [number, number][] = [];
  for (let i = 0; i + FRAME <= y.length; i += FRAME) {
    const e = ep.feed(y.slice(i, i + FRAME));
    if (e !== null) ends.push(e);
  }
  return ends;
}

const [y, speechRms] = makeStream(3);
console.log("손님이 한 말은 3번입니다.");
console.log("매장 | 고정 문턱(-38 dB)이 찾은 말 | 소음에 맞춘 문턱이 찾은 말");
const rows: [string, number, number][] = [];
for (const [name, snr] of [["조용함", null], ["SNR 20 dB", 20], ["SNR 10 dB", 10], ["SNR 5 dB", 5]] as [string, number | null][]) {
  const noisy = addStoreNoise(y, speechRms, snr);
  rows.push([name, findEnds(noisy, false).length, findEnds(noisy, true).length]);
  console.log(rows[rows.length - 1].join(" | "));
}
check(rows.length === 4 && same(rows.slice(0, 3).map((r) => r[2]), [3, 3, 3]), "소음에 맞춘 문턱은 조용함 · SNR 20 · 10 dB에서 3번을 모두 찾아야 해요.");
check(rows[0][1] === 3 && rows[2][1] < 3, "고정 문턱은 조용할 때는 3번을 찾지만, 소음이 문턱(-38 dB)을 넘으면 말의 끝을 놓쳐야 해요.");
check(speechThreshold(new Array(50).fill(-30)) === -22 && speechThreshold([]) === -42 && speechThreshold(new Array(50).fill(-70)) === -42,
  "문턱 = 소음 바닥 + 8 dB (바닥은 -50 dB 아래로 내려가지 않음, 기록이 없으면 -42 dB).");

edit.python:
# D45 · Part 4 · 확인과 수정 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d45_edit.py   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 합성은 쓰지 않음)
#   주문을 읽어 주며 확인하고(확인 문장), 손님이 말로 고치면(빼 · 바꿔) 주문서를 고쳐 다시 읽어 준다
def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


import difflib
import re

# 메뉴판 (가상). alias = 손님이 부르는 다른 이름 + 받아쓰기가 자주 틀리는 표기
MENU = {
    "아메리카노": {"price": 3000, "kind": "음료", "alias": ["아메리카노"]},
    "카페라떼": {"price": 3500, "kind": "음료", "alias": ["카페라떼", "카페라테", "라떼", "라테"]},
    "바닐라라떼": {"price": 4000, "kind": "음료", "alias": ["바닐라라떼", "바닐라라테"]},
    "녹차라떼": {"price": 4000, "kind": "음료", "alias": ["녹차라떼", "녹차라테"]},
    "유자차": {"price": 3500, "kind": "음료", "alias": ["유자차"]},
    "초코쿠키": {"price": 2000, "kind": "디저트", "alias": ["초코쿠키"]},
    "치즈케이크": {"price": 4500, "kind": "디저트", "alias": ["치즈케이크", "치즈케익"]},
}
BIG = 500  # 큰 컵은 500원 더
NUM = {"한": 1, "두": 2, "세": 3, "네": 4, "다섯": 5, "여섯": 6, "일곱": 7, "여덟": 8, "아홉": 9, "열": 10, "하나": 1, "둘": 2, "셋": 3, "넷": 4}


def exact_menu(text):
    """별명이 글 안에 그대로 있으면 그 메뉴. 긴 별명부터 찾아야 '바닐라라떼'가 '카페라떼'로 잘못 알려지지 않는다."""
    t = text.replace(" ", "")
    pairs = sorted(((a, name) for name, m in MENU.items() for a in m["alias"]), key=lambda p: -len(p[0]))
    for alias, name in pairs:
        if alias in t:
            return name
    return None


def closest_menu(text, cut=0.75):
    """받아쓰기가 틀려도 메뉴판에서 가장 닮은 메뉴 찾기. cut보다 덜 닮았으면 '모름'(None)"""
    t = re.sub(r"[ .,?!]", "", text)
    best = (0.0, None)
    for name, m in MENU.items():
        for a in m["alias"]:
            if len(a) < 4:  # 짧은 별명은 우연히 닮기 쉬워 뺌
                continue
            for L in (len(a) - 1, len(a), len(a) + 1):
                for i in range(max(len(t) - L + 1, 1)):
                    r = difflib.SequenceMatcher(None, a, t[i:i + L]).ratio()  # 두 글이 얼마나 닮았나 (0 ~ 1)
                    if r > best[0]:
                        best = (r, name)
    return best[1] if best[0] >= cut else None


def find_menu(text):
    """긴 별명이 그대로 있으면 그것 → 닮은 것 → 짧은 별명 순"""
    t = text.replace(" ", "")
    long_hit = next((n for n, m in MENU.items() for a in m["alias"] if len(a) >= 4 and a in t), None)
    return long_hit or closest_menu(text) or exact_menu(text)


def find_qty(text):
    """'두 잔' · '2개' · '하나' 같은 수량. 단위(잔·개·조각)를 꼭 본다('따뜻한'의 '한'에 속지 않게). 없으면 1"""
    t = text.replace(" ", "")
    m = re.search(r"(\d+|한|두|세|네|다섯|여섯|일곱|여덟|아홉|열)(잔|개|조각)", t)
    if m:
        return int(m.group(1)) if m.group(1).isdigit() else NUM[m.group(1)]
    m = re.search(r"하나|둘|셋|넷", t)
    return NUM[m.group(0)] if m else 1

def parse_item(text):
    """한 메뉴의 주문을 슬롯으로. temp: '-'는 해당 없음(디저트), None은 '아직 모름'(음료인데 말하지 않음)"""
    menu = find_menu(text)
    if menu is None:
        return None
    t = text.replace(" ", "")
    drink = MENU[menu]["kind"] == "음료"
    if not drink:
        temp = "-"
    elif any(w in t for w in ("아이스", "차가운", "시원한")):
        temp = "아이스"
    elif any(w in t for w in ("따뜻", "뜨거운", "핫")):
        temp = "따뜻하게"
    else:
        temp = None
    size = "큰 컵" if drink and any(w in t for w in ("큰", "라지")) else "보통"
    return {"menu": menu, "qty": find_qty(text), "temp": temp, "size": size}


def parse_items(text):
    """도전 A: 한 문장에 여러 메뉴 ('A랑 B하고 C')"""
    out = []
    for part in re.split(r"이랑|랑|하고|그리고", text.replace(" ", "").replace(",", "")):
        it = parse_item(part)
        if it:
            out.append(it)
    return out

def next_slot(order):
    """주문서를 보고 빠진 것 가운데 가장 앞의 것을 고른다(대화의 지휘자)"""
    if not order["items"]:
        return "menu"
    if any(it["temp"] is None for it in order["items"]):
        return "temp"
    if not order["done"]:
        return "more"
    if order["where"] is None:
        return "where"
    return "confirm"

def reask(n_fail):
    """연달아 못 알아들은 횟수(1부터) → (할 말, 직원을 부를지). 매번 다르게 묻고, 세 번째에는 사람을 부른다"""
    if n_fail <= 1:
        return "죄송합니다. 다시 한번 말씀해 주세요.", False
    if n_fail == 2:
        return "잘 알아듣지 못했습니다. 아메리카노 한 잔처럼 메뉴와 수량을 말씀해 주세요.", False
    return "직원을 불러 드리겠습니다. 잠시만 기다려 주세요.", True


def apply_edit(order, text):
    """말로 주문 고치기: 빼/취소/삭제 → 그 메뉴를 지움, 바꿔/변경/으로 → 수량을 바꿈. 고쳤으면 True"""
    menu = find_menu(text)
    t = text.replace(" ", "")
    hit = [it for it in order["items"] if it["menu"] == menu]
    if not hit:
        return False
    if any(w in t for w in ("빼", "취소", "삭제")):
        order["items"] = [it for it in order["items"] if it["menu"] != menu]
        return True
    if any(w in t for w in ("바꿔", "변경", "으로")):
        q = find_qty(text)
        if q < 1:  # 0잔으로는 바꾸지 않음
            return False
        hit[0]["qty"] = q
        return True
    return False


def receipt(order):
    """주문서: 한 개 값(price)과 줄 합계(sum), 전체 합계(total)는 코드가 계산한다(정수 원)"""
    rows = []
    for it in order["items"]:
        price = MENU[it["menu"]]["price"] + (BIG if it["size"] == "큰 컵" else 0)
        rows.append({**it, "price": price, "sum": price * it["qty"]})
    return {"items": rows, "where": order["where"], "total": sum(r["sum"] for r in rows)}

ASK = {"menu": "주문하실 메뉴를 말씀해 주세요.", "temp": "{menu}는 따뜻하게 드릴까요, 아이스로 드릴까요?",
       "more": "더 주문하실 것이 있으신가요?", "where": "드시고 가시나요, 포장하시나요?"}
YES, NO = ("네", "예", "맞", "응"), ("아니", "없", "됐", "그게다", "다예요", "다에요", "괜찮")
WHERE = {"포장": ("포장", "가져", "테이크"), "매장": ("매장", "먹고", "여기")}
COUNT = ["", "한", "두", "세", "네", "다섯", "여섯", "일곱", "여덟", "아홉", "열"]


def new_order():
    return {"items": [], "where": None, "done": False, "fail": 0, "state": "주문 중"}


DIGITS = "영일이삼사오육칠팔구"


def ko_under_10000(n):
    out = ""
    for unit, val in (("천", 1000), ("백", 100), ("십", 10)):
        q, n = divmod(n, val)
        if q:
            out += ("" if q == 1 else DIGITS[q]) + unit
    return out + (DIGITS[n] if n else "")


def ko_money(n):
    """13500 → '만삼천오백 원', 102000 → '십만이천 원' (합성기가 숫자를 엉뚱하게 읽지 않게 글자로). 1억 이상은 숫자 그대로"""
    if n >= 100_000_000:
        return f"{n:,} 원"
    man, rest = divmod(n, 10000)
    out = (("" if man == 1 else ko_under_10000(man)) + "만" if man else "") + ko_under_10000(rest)
    return (out or "영") + " 원"


def item_text(it):
    """한 줄을 읽기 좋게: '아이스 아메리카노 큰 컵 두 잔'"""
    unit = "잔" if MENU[it["menu"]]["kind"] == "음료" else "개"
    n = COUNT[it["qty"]] if it["qty"] <= 10 else str(it["qty"])
    words = [("아이스" if it["temp"] == "아이스" else "따뜻한" if it["temp"] == "따뜻하게" else ""),
             it["menu"], ("큰 컵" if it["size"] == "큰 컵" else "")]
    return " ".join(w for w in words if w) + f" {n} {unit}"


def confirm_text(order):
    """읽어 주며 확인 (명시적 확인)"""
    lines = ", ".join(item_text(it) for it in order["items"])
    return f"주문 확인하겠습니다. {lines}. {order['where']}, 모두 {ko_money(receipt(order)['total'])}입니다. 맞으신가요?"


def add_items(order, items):
    """같은 메뉴 · 온도 · 크기면 수량을 더함"""
    for it in items:
        same = next((o for o in order["items"] if (o["menu"], o["temp"], o["size"]) == (it["menu"], it["temp"], it["size"])), None)
        if same:
            same["qty"] += it["qty"]
        else:
            order["items"].append(it)
    order["done"] = False


def kiosk_turn(order, text):
    """대화 한 턴: 받아쓴 글로 주문서를 고치고(수정 → 메뉴 담기 → 온도 → 포장 → 아니요/네), 다음에 할 말을 돌려줌"""
    t = text.replace(" ", "")
    slot = next_slot(order)
    hit = False
    temp = "아이스" if any(w in t for w in ("아이스", "차가운", "시원한")) else "따뜻하게" if any(w in t for w in ("따뜻", "뜨거운", "핫")) else None
    where = next((k for k, ws in WHERE.items() if any(w in t for w in ws)), None)
    if order["items"] and apply_edit(order, text):  # ① 수정은 어느 단계에서든 먼저 받음
        hit = True
    else:
        removal = any(w in t for w in ("빼", "취소", "삭제"))
        items = [] if removal else parse_items(text)  # 지우라는 말인데 지울 메뉴가 없으면(위 수정이 실패) 새로 담지 않고 되묻는다
        if any(it["qty"] < 1 for it in items):  # 0잔 · 0개는 담지 않고 수량을 되묻는다
            return "수량을 다시 말씀해 주세요. 한 잔 이상으로 말씀해 주세요."
        if items:  # ② 메뉴가 들어 있으면 담음
            add_items(order, items)
            hit = True
        elif slot == "temp" and temp:
            next(it for it in order["items"] if it["temp"] is None)["temp"] = temp
            hit = True
        if where and order["items"]:  # ③ 포장 여부는 묻기 전에 말해도 받음
            order["where"] = where
            hit = True
            if slot == "more" and not items:  # "더 있으신가요?"에 "포장이요"라고 답했으면 더 없다는 뜻
                order["done"] = True
        if not hit and slot == "more" and any(w in t for w in NO):
            order["done"] = True
            hit = True
        if not hit and slot == "confirm" and any(w in t for w in NO):
            order["fail"] = 0
            return "수정할 내용을 말씀해 주세요. 예를 들면, 라떼 빼 주세요."
        if not hit and slot == "confirm" and any(w in t for w in YES):
            order["state"] = "완료"
            return f"주문이 접수되었습니다. 모두 {ko_money(receipt(order)['total'])}입니다. 카드를 꽂아 주세요."
    if not hit:  # ④ 못 알아들었으면 되묻기
        order["fail"] += 1
        msg, call_staff = reask(order["fail"])
        if call_staff:
            order["state"] = "직원 호출"
        return msg
    order["fail"] = 0
    slot = next_slot(order)  # ⑤ 고친 주문서를 보고 다음에 물을 것을 고름
    if slot == "confirm":
        return confirm_text(order)
    return ASK[slot].format(menu=next((it["menu"] for it in order["items"] if it["temp"] is None), ""))


def talk(lines, show=True):
    """글자로 하는 대화 시험: 손님의 말들을 차례로 넣어 봄"""
    order = new_order()
    if show:
        print(f"  키오스크: {ASK['menu']}")
    for line in lines:
        reply = kiosk_turn(order, line)
        if show:
            print(f"  손님: {line}\n  키오스크: {reply}")
        if order["state"] != "주문 중":
            break
    return order


def sample_order():
    return {"items": [{"menu": "아메리카노", "qty": 2, "temp": "아이스", "size": "보통"},
                      {"menu": "카페라떼", "qty": 1, "temp": "따뜻하게", "size": "보통"}], "where": "포장", "done": True}


EDITS = [("아니요카페라떼빼주세요.", True, [("아메리카노", 2)]),
         ("아메리카노 3잔으로바꿔주세요.", True, [("아메리카노", 3), ("카페라떼", 1)]),
         ("유자차 빼 주세요", False, [("아메리카노", 2), ("카페라떼", 1)]),  # 주문에 없는 메뉴는 고칠 수 없음
         ("라떼 취소해 주세요", True, [("아메리카노", 2)]),
         ("네맞아요.", False, [("아메리카노", 2), ("카페라떼", 1)])]  # 수정이 아닌 말은 건드리지 않음
results = []
for text, _, _ in EDITS:
    o = sample_order()
    r = apply_edit(o, text)
    results.append((text, r, [(i["menu"], i["qty"]) for i in o["items"]]))
    print(f"{text} → 고침 {r} · 남은 주문 {results[-1][2]}")
check(len(results) == 5 and results == EDITS, "빼 · 취소는 메뉴를 지우고, 바꿔 · 으로는 수량을 바꾸고, 그 밖의 말은 주문서를 그대로 둬야 해요.")

print("읽어 주는 확인:", confirm_text(sample_order()))
check(confirm_text(sample_order()) == "주문 확인하겠습니다. 아이스 아메리카노 두 잔, 따뜻한 카페라떼 한 잔. 포장, 모두 구천오백 원입니다. 맞으신가요?",
      "확인 문장은 메뉴 · 수량 · 포장 · 합계 금액(글자)을 읽어 줘야 해요.")

# 대화 속의 수정: 확인을 듣고 '아니요, 카페라떼 빼 주세요' → 고친 주문을 다시 읽어 준다
order = new_order()
for line in ["아이스아메리카노두잔이랑카페라떼하나주세요.", "따뜻하게주세요.", "더없어요.", "포장이요."]:
    reply = kiosk_turn(order, line)
first_confirm = reply
second_confirm = kiosk_turn(order, "아니요,카페라떼빼주세요.")
print("처음 읽어 준 것:", first_confirm)
print("고친 뒤 다시 읽어 준 것:", second_confirm)
kiosk_turn(order, "네,맞아요.")
check("카페라떼" in first_confirm and "카페라떼" not in second_confirm and order["state"] == "완료" and receipt(order)["total"] == 6000,
      "카페라떼를 빼면 다시 읽어 주는 주문에서 사라지고, 합계는 6,000원으로 끝나야 해요.")

edit.typescript:
// D45 · Part 4 · 확인과 수정 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d45_edit.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 합성은 쓰지 않음)
//   주문을 읽어 주며 확인하고(확인 문장), 손님이 말로 고치면(빼 · 바꿔) 주문서를 고쳐 다시 읽어 준다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}
const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // 값 전체가 같은지 (모양과 순서까지)

type Item = { menu: string; qty: number; temp: string | null; size: string };
type Order = { items: Item[]; where: string | null; done: boolean; fail?: number; state?: string };

// 메뉴판 (가상). alias = 손님이 부르는 다른 이름 + 받아쓰기가 자주 틀리는 표기
const MENU: Record<string, { price: number; kind: string; alias: string[] }> = {
  "아메리카노": { price: 3000, kind: "음료", alias: ["아메리카노"] },
  "카페라떼": { price: 3500, kind: "음료", alias: ["카페라떼", "카페라테", "라떼", "라테"] },
  "바닐라라떼": { price: 4000, kind: "음료", alias: ["바닐라라떼", "바닐라라테"] },
  "녹차라떼": { price: 4000, kind: "음료", alias: ["녹차라떼", "녹차라테"] },
  "유자차": { price: 3500, kind: "음료", alias: ["유자차"] },
  "초코쿠키": { price: 2000, kind: "디저트", alias: ["초코쿠키"] },
  "치즈케이크": { price: 4500, kind: "디저트", alias: ["치즈케이크", "치즈케익"] },
};
const BIG = 500; // 큰 컵은 500원 더
const NUM: Record<string, number> = { "한": 1, "두": 2, "세": 3, "네": 4, "다섯": 5, "여섯": 6, "일곱": 7, "여덟": 8, "아홉": 9, "열": 10, "하나": 1, "둘": 2, "셋": 3, "넷": 4 };
const squeeze = (s: string): string => s.replace(/ /g, "");
const has = (t: string, words: string[]): boolean => words.some((w) => t.includes(w));

// 별명이 글 안에 그대로 있으면 그 메뉴. 긴 별명부터 찾아야 '바닐라라떼'가 '카페라떼'로 잘못 알려지지 않는다.
function exactMenu(text: string): string | null {
  const t = squeeze(text);
  const pairs = Object.entries(MENU).flatMap(([name, m]) => m.alias.map((a): [string, string] => [a, name])).sort((p, q) => q[0].length - p[0].length);
  for (const [alias, name] of pairs) if (t.includes(alias)) return name;
  return null;
}

// 두 글이 얼마나 닮았나 (0 ~ 1): 가장 긴 공통 조각을 찾고 양옆을 되풀이해 센다 (Python difflib.SequenceMatcher.ratio와 같은 방식)
function ratio(a: string, b: string): number {
  const matched = (alo: number, ahi: number, blo: number, bhi: number): number => {
    let best = 0, bi = alo, bj = blo;
    for (let i = alo; i < ahi; i++) {
      for (let j = blo; j < bhi; j++) {
        let k = 0;
        while (i + k < ahi && j + k < bhi && a[i + k] === b[j + k]) k++;
        if (k > best) { best = k; bi = i; bj = j; }
      }
    }
    return best === 0 ? 0 : best + matched(alo, bi, blo, bj) + matched(bi + best, ahi, bj + best, bhi);
  };
  return a.length + b.length === 0 ? 1 : (2 * matched(0, a.length, 0, b.length)) / (a.length + b.length);
}

// 받아쓰기가 틀려도 메뉴판에서 가장 닮은 메뉴 찾기. cut보다 덜 닮았으면 '모름'(null)
function closestMenu(text: string, cut = 0.75): string | null {
  const t = text.replace(/[ .,?!]/g, "");
  let best = 0, bestName: string | null = null;
  for (const [name, m] of Object.entries(MENU)) {
    for (const a of m.alias) {
      if (a.length < 4) continue; // 짧은 별명은 우연히 닮기 쉬워 뺌
      for (const L of [a.length - 1, a.length, a.length + 1]) {
        for (let i = 0; i < Math.max(t.length - L + 1, 1); i++) {
          const r = ratio(a, t.slice(i, i + L));
          if (r > best) { best = r; bestName = name; }
        }
      }
    }
  }
  return best >= cut ? bestName : null;
}

// 긴 별명이 그대로 있으면 그것 → 닮은 것 → 짧은 별명 순
function findMenu(text: string): string | null {
  const t = squeeze(text);
  const longHit = Object.entries(MENU).find(([, m]) => m.alias.some((a) => a.length >= 4 && t.includes(a)));
  return (longHit ? longHit[0] : null) ?? closestMenu(text) ?? exactMenu(text);
}

// '두 잔' · '2개' · '하나' 같은 수량. 단위(잔·개·조각)를 꼭 본다('따뜻한'의 '한'에 속지 않게). 없으면 1
function findQty(text: string): number {
  const t = squeeze(text);
  const m = t.match(/(\d+|한|두|세|네|다섯|여섯|일곱|여덟|아홉|열)(잔|개|조각)/);
  if (m) return /^\d+$/.test(m[1]) ? Number(m[1]) : NUM[m[1]];
  const n = t.match(/하나|둘|셋|넷/);
  return n ? NUM[n[0]] : 1;
}

// 한 메뉴의 주문을 슬롯으로. temp: '-'는 해당 없음(디저트), null은 '아직 모름'(음료인데 말하지 않음)
function parseItem(text: string): Item | null {
  const menu = findMenu(text);
  if (menu === null) return null;
  const t = squeeze(text);
  const drink = MENU[menu].kind === "음료";
  let temp: string | null;
  if (!drink) temp = "-";
  else if (has(t, ["아이스", "차가운", "시원한"])) temp = "아이스";
  else if (has(t, ["따뜻", "뜨거운", "핫"])) temp = "따뜻하게";
  else temp = null;
  const size = drink && has(t, ["큰", "라지"]) ? "큰 컵" : "보통";
  return { menu, qty: findQty(text), temp, size };
}

// 도전 A: 한 문장에 여러 메뉴 ('A랑 B하고 C')
function parseItems(text: string): Item[] {
  const out: Item[] = [];
  for (const part of squeeze(text).replace(/,/g, "").split(/이랑|랑|하고|그리고/)) {
    const it = parseItem(part);
    if (it) out.push(it);
  }
  return out;
}

// 주문서를 보고 빠진 것 가운데 가장 앞의 것을 고른다(대화의 지휘자)
function nextSlot(order: Order): string {
  if (order.items.length === 0) return "menu";
  if (order.items.some((it) => it.temp === null)) return "temp";
  if (!order.done) return "more";
  if (order.where === null) return "where";
  return "confirm";
}

// 연달아 못 알아들은 횟수(1부터) → [할 말, 직원을 부를지]. 매번 다르게 묻고, 세 번째에는 사람을 부른다
function reask(nFail: number): [string, boolean] {
  if (nFail <= 1) return ["죄송합니다. 다시 한번 말씀해 주세요.", false];
  if (nFail === 2) return ["잘 알아듣지 못했습니다. 아메리카노 한 잔처럼 메뉴와 수량을 말씀해 주세요.", false];
  return ["직원을 불러 드리겠습니다. 잠시만 기다려 주세요.", true];
}

// 말로 주문 고치기: 빼/취소/삭제 → 그 메뉴를 지움, 바꿔/변경/으로 → 수량을 바꿈. 고쳤으면 true
function applyEdit(order: Order, text: string): boolean {
  const menu = findMenu(text);
  const t = squeeze(text);
  const hit = order.items.filter((it) => it.menu === menu);
  if (hit.length === 0) return false;
  if (has(t, ["빼", "취소", "삭제"])) {
    order.items = order.items.filter((it) => it.menu !== menu);
    return true;
  }
  if (has(t, ["바꿔", "변경", "으로"])) {
    const q = findQty(text);
    if (q < 1) return false; // 0잔으로는 바꾸지 않음
    hit[0].qty = q;
    return true;
  }
  return false;
}

type Row = Item & { price: number; sum: number };
// 주문서: 한 개 값(price)과 줄 합계(sum), 전체 합계(total)는 코드가 계산한다(정수 원)
function receipt(order: Order): { items: Row[]; where: string | null; total: number } {
  const rows = order.items.map((it) => {
    const price = MENU[it.menu].price + (it.size === "큰 컵" ? BIG : 0);
    return { ...it, price, sum: price * it.qty };
  });
  return { items: rows, where: order.where, total: rows.reduce((s, r) => s + r.sum, 0) };
}

const ASK: Record<string, string> = {
  menu: "주문하실 메뉴를 말씀해 주세요.", temp: "{menu}는 따뜻하게 드릴까요, 아이스로 드릴까요?",
  more: "더 주문하실 것이 있으신가요?", where: "드시고 가시나요, 포장하시나요?",
};
const YES = ["네", "예", "맞", "응"];
const NO = ["아니", "없", "됐", "그게다", "다예요", "다에요", "괜찮"];
const WHERE: Record<string, string[]> = { "포장": ["포장", "가져", "테이크"], "매장": ["매장", "먹고", "여기"] };
const COUNT = ["", "한", "두", "세", "네", "다섯", "여섯", "일곱", "여덟", "아홉", "열"];

const newOrder = (): Order => ({ items: [], where: null, done: false, fail: 0, state: "주문 중" });

const DIGITS = "영일이삼사오육칠팔구";

function koUnder10000(num: number): string {
  let out = "";
  let n = num;
  for (const [unit, val] of [["천", 1000], ["백", 100], ["십", 10]] as [string, number][]) {
    const q = Math.floor(n / val);
    n %= val;
    if (q) out += (q === 1 ? "" : DIGITS[q]) + unit;
  }
  return out + (n ? DIGITS[n] : "");
}

// 13500 → '만삼천오백 원', 102000 → '십만이천 원' (합성기가 숫자를 엉뚱하게 읽지 않게 글자로). 1억 이상은 숫자 그대로
function koMoney(n: number): string {
  if (n >= 100_000_000) return `${n.toLocaleString("en-US")} 원`;
  const man = Math.floor(n / 10000);
  const out = (man ? (man === 1 ? "" : koUnder10000(man)) + "만" : "") + koUnder10000(n % 10000);
  return (out || "영") + " 원";
}

// 한 줄을 읽기 좋게: '아이스 아메리카노 큰 컵 두 잔'
function itemText(it: Item): string {
  const unit = MENU[it.menu].kind === "음료" ? "잔" : "개";
  const n = it.qty <= 10 ? COUNT[it.qty] : String(it.qty);
  const words = [it.temp === "아이스" ? "아이스" : it.temp === "따뜻하게" ? "따뜻한" : "", it.menu, it.size === "큰 컵" ? "큰 컵" : ""];
  return `${words.filter((w) => w).join(" ")} ${n} ${unit}`;
}

// 읽어 주며 확인 (명시적 확인)
function confirmText(order: Order): string {
  return `주문 확인하겠습니다. ${order.items.map(itemText).join(", ")}. ${order.where}, 모두 ${koMoney(receipt(order).total)}입니다. 맞으신가요?`;
}

// 같은 메뉴 · 온도 · 크기면 수량을 더함
function addItems(order: Order, items: Item[]): void {
  for (const it of items) {
    const found = order.items.find((o) => o.menu === it.menu && o.temp === it.temp && o.size === it.size);
    if (found) found.qty += it.qty;
    else order.items.push(it);
  }
  order.done = false;
}

// 대화 한 턴: 받아쓴 글로 주문서를 고치고(수정 → 메뉴 담기 → 온도 → 포장 → 아니요/네), 다음에 할 말을 돌려줌
function kioskTurn(order: Order, text: string): string {
  const t = squeeze(text);
  let slot = nextSlot(order);
  let hit = false;
  const temp = has(t, ["아이스", "차가운", "시원한"]) ? "아이스" : has(t, ["따뜻", "뜨거운", "핫"]) ? "따뜻하게" : null;
  const where = Object.keys(WHERE).find((k) => has(t, WHERE[k])) ?? null;
  if (order.items.length > 0 && applyEdit(order, text)) {
    hit = true; // ① 수정은 어느 단계에서든 먼저 받음
  } else {
    const removal = has(t, ["빼", "취소", "삭제"]);
    const items = removal ? [] : parseItems(text); // 지우라는 말인데 지울 메뉴가 없으면(위 수정이 실패) 새로 담지 않고 되묻는다
    if (parseItems(text).some((it) => it.qty < 1) && !removal) return "수량을 다시 말씀해 주세요. 한 잔 이상으로 말씀해 주세요."; // 0잔 · 0개는 담지 않고 수량을 되묻는다
    if (items.length > 0) {
      addItems(order, items); // ② 메뉴가 들어 있으면 담음
      hit = true;
    } else if (slot === "temp" && temp) {
      order.items.find((it) => it.temp === null)!.temp = temp;
      hit = true;
    }
    if (where && order.items.length > 0) { // ③ 포장 여부는 묻기 전에 말해도 받음
      order.where = where;
      hit = true;
      if (slot === "more" && items.length === 0) order.done = true; // "더 있으신가요?"에 "포장이요"라고 답했으면 더 없다는 뜻
    }
    if (!hit && slot === "more" && has(t, NO)) {
      order.done = true;
      hit = true;
    }
    if (!hit && slot === "confirm" && has(t, NO)) {
      order.fail = 0;
      return "수정할 내용을 말씀해 주세요. 예를 들면, 라떼 빼 주세요.";
    }
    if (!hit && slot === "confirm" && has(t, YES)) {
      order.state = "완료";
      return `주문이 접수되었습니다. 모두 ${koMoney(receipt(order).total)}입니다. 카드를 꽂아 주세요.`;
    }
  }
  if (!hit) { // ④ 못 알아들었으면 되묻기
    order.fail = (order.fail ?? 0) + 1;
    const [msg, callStaff] = reask(order.fail);
    if (callStaff) order.state = "직원 호출";
    return msg;
  }
  order.fail = 0;
  slot = nextSlot(order); // ⑤ 고친 주문서를 보고 다음에 물을 것을 고름
  if (slot === "confirm") return confirmText(order);
  return ASK[slot].replace("{menu}", order.items.find((it) => it.temp === null)?.menu ?? "");
}

// 글자로 하는 대화 시험: 손님의 말들을 차례로 넣어 봄
function talk(lines: string[], show = true): Order {
  const order = newOrder();
  if (show) console.log(`  키오스크: ${ASK.menu}`);
  for (const line of lines) {
    const reply = kioskTurn(order, line);
    if (show) console.log(`  손님: ${line}\n  키오스크: ${reply}`);
    if (order.state !== "주문 중") break;
  }
  return order;
}

const sampleOrder = (): Order => ({
  items: [{ menu: "아메리카노", qty: 2, temp: "아이스", size: "보통" }, { menu: "카페라떼", qty: 1, temp: "따뜻하게", size: "보통" }],
  where: "포장", done: true,
});

type Edit = [string, boolean, [string, number][]];
const EDITS: Edit[] = [
  ["아니요카페라떼빼주세요.", true, [["아메리카노", 2]]],
  ["아메리카노 3잔으로바꿔주세요.", true, [["아메리카노", 3], ["카페라떼", 1]]],
  ["유자차 빼 주세요", false, [["아메리카노", 2], ["카페라떼", 1]]], // 주문에 없는 메뉴는 고칠 수 없음
  ["라떼 취소해 주세요", true, [["아메리카노", 2]]],
  ["네맞아요.", false, [["아메리카노", 2], ["카페라떼", 1]]], // 수정이 아닌 말은 건드리지 않음
];
const results: Edit[] = EDITS.map(([text]) => {
  const o = sampleOrder();
  const r = applyEdit(o, text);
  console.log(`${text} → 고침 ${r} · 남은 주문 ${JSON.stringify(o.items.map((i) => [i.menu, i.qty]))}`);
  return [text, r, o.items.map((i): [string, number] => [i.menu, i.qty])];
});
check(results.length === 5 && same(results, EDITS), "빼 · 취소는 메뉴를 지우고, 바꿔 · 으로는 수량을 바꾸고, 그 밖의 말은 주문서를 그대로 둬야 해요.");

console.log("읽어 주는 확인:", confirmText(sampleOrder()));
check(confirmText(sampleOrder()) === "주문 확인하겠습니다. 아이스 아메리카노 두 잔, 따뜻한 카페라떼 한 잔. 포장, 모두 구천오백 원입니다. 맞으신가요?",
  "확인 문장은 메뉴 · 수량 · 포장 · 합계 금액(글자)을 읽어 줘야 해요.");

// 대화 속의 수정: 확인을 듣고 '아니요, 카페라떼 빼 주세요' → 고친 주문을 다시 읽어 준다
const order = newOrder();
let reply = "";
for (const line of ["아이스아메리카노두잔이랑카페라떼하나주세요.", "따뜻하게주세요.", "더없어요.", "포장이요."]) reply = kioskTurn(order, line);
const firstConfirm = reply;
const secondConfirm = kioskTurn(order, "아니요,카페라떼빼주세요.");
console.log("처음 읽어 준 것:", firstConfirm);
console.log("고친 뒤 다시 읽어 준 것:", secondConfirm);
kioskTurn(order, "네,맞아요.");
check(firstConfirm.includes("카페라떼") && !secondConfirm.includes("카페라떼") && order.state === "완료" && receipt(order).total === 6000,
  "카페라떼를 빼면 다시 읽어 주는 주문에서 사라지고, 합계는 6,000원으로 끝나야 해요.");

receipt.typescript:
// D45 · Part 4 · 주문서와 점수판 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d45_receipt.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 합성은 쓰지 않음)
//   금액은 코드가 계산한 주문서(JSON, 정수 원)를 만들고, 도전 A(여러 메뉴)·B(어르신용 느린 말)와 체크포인트 점수판을 실제로 채점한다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}
const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // 값 전체가 같은지 (모양과 순서까지)

type Item = { menu: string; qty: number; temp: string | null; size: string };
type Order = { items: Item[]; where: string | null; done: boolean; fail?: number; state?: string };

// 메뉴판 (가상). alias = 손님이 부르는 다른 이름 + 받아쓰기가 자주 틀리는 표기
const MENU: Record<string, { price: number; kind: string; alias: string[] }> = {
  "아메리카노": { price: 3000, kind: "음료", alias: ["아메리카노"] },
  "카페라떼": { price: 3500, kind: "음료", alias: ["카페라떼", "카페라테", "라떼", "라테"] },
  "바닐라라떼": { price: 4000, kind: "음료", alias: ["바닐라라떼", "바닐라라테"] },
  "녹차라떼": { price: 4000, kind: "음료", alias: ["녹차라떼", "녹차라테"] },
  "유자차": { price: 3500, kind: "음료", alias: ["유자차"] },
  "초코쿠키": { price: 2000, kind: "디저트", alias: ["초코쿠키"] },
  "치즈케이크": { price: 4500, kind: "디저트", alias: ["치즈케이크", "치즈케익"] },
};
const BIG = 500; // 큰 컵은 500원 더
const NUM: Record<string, number> = { "한": 1, "두": 2, "세": 3, "네": 4, "다섯": 5, "여섯": 6, "일곱": 7, "여덟": 8, "아홉": 9, "열": 10, "하나": 1, "둘": 2, "셋": 3, "넷": 4 };
const squeeze = (s: string): string => s.replace(/ /g, "");
const has = (t: string, words: string[]): boolean => words.some((w) => t.includes(w));

// 별명이 글 안에 그대로 있으면 그 메뉴. 긴 별명부터 찾아야 '바닐라라떼'가 '카페라떼'로 잘못 알려지지 않는다.
function exactMenu(text: string): string | null {
  const t = squeeze(text);
  const pairs = Object.entries(MENU).flatMap(([name, m]) => m.alias.map((a): [string, string] => [a, name])).sort((p, q) => q[0].length - p[0].length);
  for (const [alias, name] of pairs) if (t.includes(alias)) return name;
  return null;
}

// 두 글이 얼마나 닮았나 (0 ~ 1): 가장 긴 공통 조각을 찾고 양옆을 되풀이해 센다 (Python difflib.SequenceMatcher.ratio와 같은 방식)
function ratio(a: string, b: string): number {
  const matched = (alo: number, ahi: number, blo: number, bhi: number): number => {
    let best = 0, bi = alo, bj = blo;
    for (let i = alo; i < ahi; i++) {
      for (let j = blo; j < bhi; j++) {
        let k = 0;
        while (i + k < ahi && j + k < bhi && a[i + k] === b[j + k]) k++;
        if (k > best) { best = k; bi = i; bj = j; }
      }
    }
    return best === 0 ? 0 : best + matched(alo, bi, blo, bj) + matched(bi + best, ahi, bj + best, bhi);
  };
  return a.length + b.length === 0 ? 1 : (2 * matched(0, a.length, 0, b.length)) / (a.length + b.length);
}

// 받아쓰기가 틀려도 메뉴판에서 가장 닮은 메뉴 찾기. cut보다 덜 닮았으면 '모름'(null)
function closestMenu(text: string, cut = 0.75): string | null {
  const t = text.replace(/[ .,?!]/g, "");
  let best = 0, bestName: string | null = null;
  for (const [name, m] of Object.entries(MENU)) {
    for (const a of m.alias) {
      if (a.length < 4) continue; // 짧은 별명은 우연히 닮기 쉬워 뺌
      for (const L of [a.length - 1, a.length, a.length + 1]) {
        for (let i = 0; i < Math.max(t.length - L + 1, 1); i++) {
          const r = ratio(a, t.slice(i, i + L));
          if (r > best) { best = r; bestName = name; }
        }
      }
    }
  }
  return best >= cut ? bestName : null;
}

// 긴 별명이 그대로 있으면 그것 → 닮은 것 → 짧은 별명 순
function findMenu(text: string): string | null {
  const t = squeeze(text);
  const longHit = Object.entries(MENU).find(([, m]) => m.alias.some((a) => a.length >= 4 && t.includes(a)));
  return (longHit ? longHit[0] : null) ?? closestMenu(text) ?? exactMenu(text);
}

// '두 잔' · '2개' · '하나' 같은 수량. 단위(잔·개·조각)를 꼭 본다('따뜻한'의 '한'에 속지 않게). 없으면 1
function findQty(text: string): number {
  const t = squeeze(text);
  const m = t.match(/(\d+|한|두|세|네|다섯|여섯|일곱|여덟|아홉|열)(잔|개|조각)/);
  if (m) return /^\d+$/.test(m[1]) ? Number(m[1]) : NUM[m[1]];
  const n = t.match(/하나|둘|셋|넷/);
  return n ? NUM[n[0]] : 1;
}

// 한 메뉴의 주문을 슬롯으로. temp: '-'는 해당 없음(디저트), null은 '아직 모름'(음료인데 말하지 않음)
function parseItem(text: string): Item | null {
  const menu = findMenu(text);
  if (menu === null) return null;
  const t = squeeze(text);
  const drink = MENU[menu].kind === "음료";
  let temp: string | null;
  if (!drink) temp = "-";
  else if (has(t, ["아이스", "차가운", "시원한"])) temp = "아이스";
  else if (has(t, ["따뜻", "뜨거운", "핫"])) temp = "따뜻하게";
  else temp = null;
  const size = drink && has(t, ["큰", "라지"]) ? "큰 컵" : "보통";
  return { menu, qty: findQty(text), temp, size };
}

// 도전 A: 한 문장에 여러 메뉴 ('A랑 B하고 C')
function parseItems(text: string): Item[] {
  const out: Item[] = [];
  for (const part of squeeze(text).replace(/,/g, "").split(/이랑|랑|하고|그리고/)) {
    const it = parseItem(part);
    if (it) out.push(it);
  }
  return out;
}

// 주문서를 보고 빠진 것 가운데 가장 앞의 것을 고른다(대화의 지휘자)
function nextSlot(order: Order): string {
  if (order.items.length === 0) return "menu";
  if (order.items.some((it) => it.temp === null)) return "temp";
  if (!order.done) return "more";
  if (order.where === null) return "where";
  return "confirm";
}

// 연달아 못 알아들은 횟수(1부터) → [할 말, 직원을 부를지]. 매번 다르게 묻고, 세 번째에는 사람을 부른다
function reask(nFail: number): [string, boolean] {
  if (nFail <= 1) return ["죄송합니다. 다시 한번 말씀해 주세요.", false];
  if (nFail === 2) return ["잘 알아듣지 못했습니다. 아메리카노 한 잔처럼 메뉴와 수량을 말씀해 주세요.", false];
  return ["직원을 불러 드리겠습니다. 잠시만 기다려 주세요.", true];
}

// 말로 주문 고치기: 빼/취소/삭제 → 그 메뉴를 지움, 바꿔/변경/으로 → 수량을 바꿈. 고쳤으면 true
function applyEdit(order: Order, text: string): boolean {
  const menu = findMenu(text);
  const t = squeeze(text);
  const hit = order.items.filter((it) => it.menu === menu);
  if (hit.length === 0) return false;
  if (has(t, ["빼", "취소", "삭제"])) {
    order.items = order.items.filter((it) => it.menu !== menu);
    return true;
  }
  if (has(t, ["바꿔", "변경", "으로"])) {
    const q = findQty(text);
    if (q < 1) return false; // 0잔으로는 바꾸지 않음
    hit[0].qty = q;
    return true;
  }
  return false;
}

type Row = Item & { price: number; sum: number };
// 주문서: 한 개 값(price)과 줄 합계(sum), 전체 합계(total)는 코드가 계산한다(정수 원)
function receipt(order: Order): { items: Row[]; where: string | null; total: number } {
  const rows = order.items.map((it) => {
    const price = MENU[it.menu].price + (it.size === "큰 컵" ? BIG : 0);
    return { ...it, price, sum: price * it.qty };
  });
  return { items: rows, where: order.where, total: rows.reduce((s, r) => s + r.sum, 0) };
}

const SR = 16000;
const FRAME = SR / 50; // 20 ms 조각 = 320 샘플

// 아래에서 q% 자리의 값 (numpy.percentile의 기본 방식: 이웃한 두 값 사이를 직선으로)
function percentile(xs: number[], q: number): number {
  const s = [...xs].sort((a, b) => a - b);
  const pos = ((s.length - 1) * q) / 100;
  const lo = Math.floor(pos);
  const hi = Math.min(lo + 1, s.length - 1);
  return s[lo] + (s[hi] - s[lo]) * (pos - lo);
}

// 소음에 맞춘 문턱 = 소음 바닥(아래에서 10% 자리) + margin. 평균이 아니라 10% 자리를 쓰는 까닭: 손님의 말이 섞여도 바닥이 오르지 않게
function speechThreshold(dbHistory: number[], margin = 8.0, lowest = -50.0): number {
  if (dbHistory.length === 0) return lowest + margin;
  return Math.max(percentile(dbHistory, 10), lowest) + margin;
}

// 도전 B: [말할 조각, 빠르기]. 어르신용은 문장 부호 뒤에서 잘라 0.8배속으로
function speakPlan(text: string, senior = false): [string, number][] {
  if (!senior) return [[text, 1.0]];
  return text.split(/(?<=[.?!,])\s*/).filter((p) => p.trim()).map((p): [string, number] => [p, 0.8]);
}

function tryEdit(text: string): [boolean, [string, number][]] {
  const o: Order = {
    items: [{ menu: "아메리카노", qty: 2, temp: "아이스", size: "보통" }, { menu: "카페라떼", qty: 1, temp: "따뜻하게", size: "보통" }],
    where: "포장", done: true,
  };
  const r = applyEdit(o, text);
  return [r, o.items.map((i): [string, number] => [i.menu, i.qty])];
}

function tryReceipt(items: Item[], where: string | null): [number, [string, number, number][], string | null] {
  const r = receipt({ items, where, done: true });
  return [r.total, r.items.map((i): [string, number, number] => [i.menu, i.price, i.sum]), r.where];
}

const A: Item = { menu: "아메리카노", qty: 2, temp: "아이스", size: "보통" };
const L: Item = { menu: "카페라떼", qty: 1, temp: null, size: "보통" };
const BV: Item = { menu: "바닐라라떼", qty: 1, temp: "따뜻하게", size: "큰 컵" };
const CK: Item = { menu: "초코쿠키", qty: 2, temp: "-", size: "보통" };
const T = "주문 확인하겠습니다. 아이스 아메리카노 두 잔, 초코쿠키 두 개. 포장, 모두 만 원입니다. 맞으신가요?";

// [번호, 이름, 점수, 시험할 함수, [[인자들, 기대값], ...]]  — 체크포인트 ①~⑧ 각 10점, 도전 A·B 각 +10점
type Case = [unknown[], unknown];
const BOARD: [string, string, number, (...a: any[]) => unknown, Case[]][] = [
  ["①", "메뉴 찾기", 10, findMenu, [
    [["아이스아메리카노두잔주세요."], "아메리카노"], [["바닐라라떼 큰 걸로 하나"], "바닐라라떼"], [["라떼 한 잔이요"], "카페라떼"],
    [["카페라테하나"], "카페라떼"], [["치즈케익 하나요"], "치즈케이크"], [["포장이요"], null]]],
  ["②", "수량 찾기", 10, findQty, [
    [["아이스아메리카노두잔주세요."], 2], [["초코쿠키 2개주세요"], 2], [["치즈케이크하나요"], 1], [["따뜻한 카페라떼 주세요"], 1],
    [["네, 맞아요"], 1], [["유자차 열 잔"], 10], [["케이크 세 조각"], 3]]],
  ["③", "한 메뉴의 주문", 10, parseItem, [
    [["아이스아메리카노두잔주세요."], { menu: "아메리카노", qty: 2, temp: "아이스", size: "보통" }],
    [["따뜻한 카페라떼 한 잔이요"], { menu: "카페라떼", qty: 1, temp: "따뜻하게", size: "보통" }],
    [["바닐라라떼큰걸로하나주세요."], { menu: "바닐라라떼", qty: 1, temp: null, size: "큰 컵" }],
    [["초코쿠키 2개주세요"], CK], [["유자차 세 잔"], { menu: "유자차", qty: 3, temp: null, size: "보통" }], [["포장이요"], null]]],
  ["④", "다음에 물을 것", 10, nextSlot, [
    [[{ items: [], where: null, done: false }], "menu"], [[{ items: [A, L], where: null, done: false }], "temp"],
    [[{ items: [A], where: null, done: false }], "more"], [[{ items: [A], where: null, done: true }], "where"],
    [[{ items: [A], where: "포장", done: true }], "confirm"]]],
  ["⑤", "소음에 맞춘 문턱", 10, speechThreshold, [
    [[new Array(50).fill(-30)], -22], [[new Array(50).fill(-70)], -42], [[[]], -42], [[new Array(50).fill(-30), 12], -18]]],
  ["⑥", "되묻기와 직원 호출", 10, reask, [
    [[1], ["죄송합니다. 다시 한번 말씀해 주세요.", false]],
    [[2], ["잘 알아듣지 못했습니다. 아메리카노 한 잔처럼 메뉴와 수량을 말씀해 주세요.", false]],
    [[3], ["직원을 불러 드리겠습니다. 잠시만 기다려 주세요.", true]], [[5], ["직원을 불러 드리겠습니다. 잠시만 기다려 주세요.", true]]]],
  ["⑦", "주문 고치기", 10, tryEdit, [
    [["아니요카페라떼빼주세요."], [true, [["아메리카노", 2]]]], [["아메리카노 3잔으로바꿔주세요."], [true, [["아메리카노", 3], ["카페라떼", 1]]]],
    [["유자차 빼 주세요"], [false, [["아메리카노", 2], ["카페라떼", 1]]]], [["라떼 취소해 주세요"], [true, [["아메리카노", 2]]]],
    [["네맞아요."], [false, [["아메리카노", 2], ["카페라떼", 1]]]]]],
  ["⑧", "주문서", 10, tryReceipt, [
    [[[A, BV], "포장"], [10500, [["아메리카노", 3000, 6000], ["바닐라라떼", 4500, 4500]], "포장"]],
    [[[CK], "매장"], [4000, [["초코쿠키", 2000, 4000]], "매장"]], [[[], null], [0, [], null]]]],
  ["A", "도전 A 여러 메뉴를 한 번에", 10, parseItems, [
    [["아이스아메리카노두잔이랑카페라떼하나주세요"], [{ menu: "아메리카노", qty: 2, temp: "아이스", size: "보통" }, L]], [["메뉴가 아닌 말"], []]]],
  ["B", "도전 B 어르신용 느린 말", 10, speakPlan, [
    [[T], [[T, 1.0]]],
    [[T, true], [["주문 확인하겠습니다.", 0.8], ["아이스 아메리카노 두 잔,", 0.8], ["초코쿠키 두 개.", 0.8], ["포장,", 0.8], ["모두 만 원입니다.", 0.8], ["맞으신가요?", 0.8]]]]],
];

// 모든 체크포인트를 실제로 돌려 보고 통과한 것의 점수를 모은다. 돌려주는 값: [번호, 이름, 얻은 점수, 시험 개수][]
function grade(): [string, string, number, number][] {
  return BOARD.map(([no, name, pts, f, cases]) => {
    const got = cases.map(([args]) => f(...args));
    const ok = cases.length > 0 && same(got, cases.map(([, want]) => want));
    return [no, name, ok ? pts : 0, cases.length];
  });
}

const order: Order = { items: [parseItem("아이스아메리카노두잔주세요.")!, parseItem("바닐라라떼큰걸로하나주세요.")!], where: "포장", done: true };
order.items[1].temp = "따뜻하게";
const rec = receipt(order);
console.log("주문서:", JSON.stringify(rec));
check(rec.total === 10500 && same(rec.items.map((r) => r.sum), [6000, 4500]) && rec.items.every((r) => Number.isInteger(r.price)),
  "아메리카노 2잔 6,000원 + 큰 컵 바닐라라떼 1잔 4,500원(큰 컵 +500) = 10,500원, 금액은 모두 정수여야 해요.");

console.log("도전 A:", JSON.stringify(parseItems("아이스아메리카노두잔이랑카페라떼하나주세요")));
console.log("도전 B:", JSON.stringify(speakPlan("주문 확인하겠습니다. 포장, 모두 만 원입니다. 맞으신가요?", true)));

const rows = grade();
console.log("점수판");
for (const [no, name, pts, n] of rows) console.log(`  ${no} ${name}: ${pts}점 (시험 ${n}개)`);
const total = rows.reduce((s, r) => s + r[2], 0);
console.log(`합계 ${total}점`);
check(rows.length === 10 && total === 100, "체크포인트 8개(각 10점)와 도전 A · B(각 +10점)를 모두 통과하면 100점이에요.");

recap.typescript:
// D45 · Part 5 · 정리 퀴즈 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d45_recap.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 합성은 쓰지 않음)
//   '오늘 만든 것 · 배운 것' 여섯 줄을 한 줄씩 실제 코드로 확인한다(긴 별명부터 · 다음 질문은 주문서에서 계산 · 다시 재기 · 문턱 · 되묻기 · 금액은 코드가)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}
const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // 값 전체가 같은지 (모양과 순서까지)

type Item = { menu: string; qty: number; temp: string | null; size: string };
type Order = { items: Item[]; where: string | null; done: boolean; fail?: number; state?: string };

// 메뉴판 (가상). alias = 손님이 부르는 다른 이름 + 받아쓰기가 자주 틀리는 표기
const MENU: Record<string, { price: number; kind: string; alias: string[] }> = {
  "아메리카노": { price: 3000, kind: "음료", alias: ["아메리카노"] },
  "카페라떼": { price: 3500, kind: "음료", alias: ["카페라떼", "카페라테", "라떼", "라테"] },
  "바닐라라떼": { price: 4000, kind: "음료", alias: ["바닐라라떼", "바닐라라테"] },
  "녹차라떼": { price: 4000, kind: "음료", alias: ["녹차라떼", "녹차라테"] },
  "유자차": { price: 3500, kind: "음료", alias: ["유자차"] },
  "초코쿠키": { price: 2000, kind: "디저트", alias: ["초코쿠키"] },
  "치즈케이크": { price: 4500, kind: "디저트", alias: ["치즈케이크", "치즈케익"] },
};
const BIG = 500; // 큰 컵은 500원 더
const NUM: Record<string, number> = { "한": 1, "두": 2, "세": 3, "네": 4, "다섯": 5, "여섯": 6, "일곱": 7, "여덟": 8, "아홉": 9, "열": 10, "하나": 1, "둘": 2, "셋": 3, "넷": 4 };
const squeeze = (s: string): string => s.replace(/ /g, "");
const has = (t: string, words: string[]): boolean => words.some((w) => t.includes(w));

// 별명이 글 안에 그대로 있으면 그 메뉴. 긴 별명부터 찾아야 '바닐라라떼'가 '카페라떼'로 잘못 알려지지 않는다.
function exactMenu(text: string): string | null {
  const t = squeeze(text);
  const pairs = Object.entries(MENU).flatMap(([name, m]) => m.alias.map((a): [string, string] => [a, name])).sort((p, q) => q[0].length - p[0].length);
  for (const [alias, name] of pairs) if (t.includes(alias)) return name;
  return null;
}

// 두 글이 얼마나 닮았나 (0 ~ 1): 가장 긴 공통 조각을 찾고 양옆을 되풀이해 센다 (Python difflib.SequenceMatcher.ratio와 같은 방식)
function ratio(a: string, b: string): number {
  const matched = (alo: number, ahi: number, blo: number, bhi: number): number => {
    let best = 0, bi = alo, bj = blo;
    for (let i = alo; i < ahi; i++) {
      for (let j = blo; j < bhi; j++) {
        let k = 0;
        while (i + k < ahi && j + k < bhi && a[i + k] === b[j + k]) k++;
        if (k > best) { best = k; bi = i; bj = j; }
      }
    }
    return best === 0 ? 0 : best + matched(alo, bi, blo, bj) + matched(bi + best, ahi, bj + best, bhi);
  };
  return a.length + b.length === 0 ? 1 : (2 * matched(0, a.length, 0, b.length)) / (a.length + b.length);
}

// 받아쓰기가 틀려도 메뉴판에서 가장 닮은 메뉴 찾기. cut보다 덜 닮았으면 '모름'(null)
function closestMenu(text: string, cut = 0.75): string | null {
  const t = text.replace(/[ .,?!]/g, "");
  let best = 0, bestName: string | null = null;
  for (const [name, m] of Object.entries(MENU)) {
    for (const a of m.alias) {
      if (a.length < 4) continue; // 짧은 별명은 우연히 닮기 쉬워 뺌
      for (const L of [a.length - 1, a.length, a.length + 1]) {
        for (let i = 0; i < Math.max(t.length - L + 1, 1); i++) {
          const r = ratio(a, t.slice(i, i + L));
          if (r > best) { best = r; bestName = name; }
        }
      }
    }
  }
  return best >= cut ? bestName : null;
}

// 긴 별명이 그대로 있으면 그것 → 닮은 것 → 짧은 별명 순
function findMenu(text: string): string | null {
  const t = squeeze(text);
  const longHit = Object.entries(MENU).find(([, m]) => m.alias.some((a) => a.length >= 4 && t.includes(a)));
  return (longHit ? longHit[0] : null) ?? closestMenu(text) ?? exactMenu(text);
}

// '두 잔' · '2개' · '하나' 같은 수량. 단위(잔·개·조각)를 꼭 본다('따뜻한'의 '한'에 속지 않게). 없으면 1
function findQty(text: string): number {
  const t = squeeze(text);
  const m = t.match(/(\d+|한|두|세|네|다섯|여섯|일곱|여덟|아홉|열)(잔|개|조각)/);
  if (m) return /^\d+$/.test(m[1]) ? Number(m[1]) : NUM[m[1]];
  const n = t.match(/하나|둘|셋|넷/);
  return n ? NUM[n[0]] : 1;
}

// 주문서를 보고 빠진 것 가운데 가장 앞의 것을 고른다(대화의 지휘자)
function nextSlot(order: Order): string {
  if (order.items.length === 0) return "menu";
  if (order.items.some((it) => it.temp === null)) return "temp";
  if (!order.done) return "more";
  if (order.where === null) return "where";
  return "confirm";
}

// 연달아 못 알아들은 횟수(1부터) → [할 말, 직원을 부를지]. 매번 다르게 묻고, 세 번째에는 사람을 부른다
function reask(nFail: number): [string, boolean] {
  if (nFail <= 1) return ["죄송합니다. 다시 한번 말씀해 주세요.", false];
  if (nFail === 2) return ["잘 알아듣지 못했습니다. 아메리카노 한 잔처럼 메뉴와 수량을 말씀해 주세요.", false];
  return ["직원을 불러 드리겠습니다. 잠시만 기다려 주세요.", true];
}

// 말로 주문 고치기: 빼/취소/삭제 → 그 메뉴를 지움, 바꿔/변경/으로 → 수량을 바꿈. 고쳤으면 true
function applyEdit(order: Order, text: string): boolean {
  const menu = findMenu(text);
  const t = squeeze(text);
  const hit = order.items.filter((it) => it.menu === menu);
  if (hit.length === 0) return false;
  if (has(t, ["빼", "취소", "삭제"])) {
    order.items = order.items.filter((it) => it.menu !== menu);
    return true;
  }
  if (has(t, ["바꿔", "변경", "으로"])) {
    const q = findQty(text);
    if (q < 1) return false; // 0잔으로는 바꾸지 않음
    hit[0].qty = q;
    return true;
  }
  return false;
}

type Row = Item & { price: number; sum: number };
// 주문서: 한 개 값(price)과 줄 합계(sum), 전체 합계(total)는 코드가 계산한다(정수 원)
function receipt(order: Order): { items: Row[]; where: string | null; total: number } {
  const rows = order.items.map((it) => {
    const price = MENU[it.menu].price + (it.size === "큰 컵" ? BIG : 0);
    return { ...it, price, sum: price * it.qty };
  });
  return { items: rows, where: order.where, total: rows.reduce((s, r) => s + r.sum, 0) };
}

const SR = 16000;
const FRAME = SR / 50; // 20 ms 조각 = 320 샘플

// 아래에서 q% 자리의 값 (numpy.percentile의 기본 방식: 이웃한 두 값 사이를 직선으로)
function percentile(xs: number[], q: number): number {
  const s = [...xs].sort((a, b) => a - b);
  const pos = ((s.length - 1) * q) / 100;
  const lo = Math.floor(pos);
  const hi = Math.min(lo + 1, s.length - 1);
  return s[lo] + (s[hi] - s[lo]) * (pos - lo);
}

// 소음에 맞춘 문턱 = 소음 바닥(아래에서 10% 자리) + margin. 평균이 아니라 10% 자리를 쓰는 까닭: 손님의 말이 섞여도 바닥이 오르지 않게
function speechThreshold(dbHistory: number[], margin = 8.0, lowest = -50.0): number {
  if (dbHistory.length === 0) return lowest + margin;
  return Math.max(percentile(dbHistory, 10), lowest) + margin;
}

// ① ② 답이 정해진 곳에서는 정해진 답에 맞춰 듣는다. 겹치는 낱말은 긴 것부터
const t = "바닐라라떼큰걸로하나";
const naive = Object.entries(MENU).find(([, m]) => m.alias.some((a) => t.includes(a)))?.[0] ?? null; // 메뉴판 순서대로 처음 걸린 별명 → '라떼'에 걸림
console.log("메뉴판 순서로 찾으면:", naive, "· 긴 별명부터 찾으면:", exactMenu(t));
check(naive === "카페라떼" && exactMenu(t) === "바닐라라떼", "긴 별명부터 찾아야 '바닐라라떼'를 카페라떼로 잘못 알지 않아요.");

// ③ ④ 다음 질문은 주문서의 상태에서 계산한다
const a: Item = { menu: "아메리카노", qty: 1, temp: null, size: "보통" };
const before = nextSlot({ items: [a], where: null, done: false });
const after = nextSlot({ items: [{ ...a, temp: "아이스" }], where: null, done: false });
console.log("온도를 모를 때:", before, "· 온도를 알게 된 뒤:", after);
check(before === "temp" && after === "more", "같은 손님이라도 주문서가 바뀌면 다음 질문이 달라져야 해요.");

// 소음 실험: 소리가 깨끗해진 것과 주문이 맞는 것은 다르다 → 목표로 삼은 숫자(주문 정확도)로 다시 잰다
const PAIRS: [string, string][] = [["바닐라라라떼큰걸로하나주세요.", "바닐라라떼"], ["아닐라라라떼꿈.", "바닐라라떼"], ["아메리카누한잔", "아메리카노"],
  ["라떼빼주세요.", "카페라떼"], ["아이스아메리카노두잔주세요.", "아메리카노"], ["치즈케익하나요", "치즈케이크"]];
const accExact = PAIRS.filter(([h, w]) => exactMenu(h) === w).length / PAIRS.length;
const accFit = PAIRS.filter(([h, w]) => findMenu(h) === w).length / PAIRS.length;
console.log(`주문(메뉴) 정확도: 별명 그대로 ${accExact.toFixed(2)} · 메뉴판에 맞춰 ${accFit.toFixed(2)}`);
check(PAIRS.length === 6 && accFit === 1.0 && accFit > accExact, "메뉴판에 맞춰 들으면 별명 그대로보다 정확해야 해요(틀린 받아쓰기도 구해냄).");

// ⑤ 받아쓰기보다 먼저 말의 끝을 찾는 것이 무너진다 → 문턱을 소음에 맞춘다
const quietTh = speechThreshold(new Array(50).fill(-60));
const noisyTh = speechThreshold(new Array(50).fill(-30));
console.log(`조용한 매장의 문턱 ${quietTh} dB · 시끄러운 매장의 문턱 ${noisyTh} dB`);
check(quietTh === -42 && noisyTh === -22 && noisyTh > quietTh, "소음 바닥이 오르면 문턱도 올라가고, 바닥은 -50 dB 아래로 내려가지 않아야 해요.");

// ⑥ 되묻기: 매번 다르게 묻고, 세 번째에는 사람을 부른다
const replies = [1, 2, 3].map(reask);
for (const r of replies) console.log(JSON.stringify(r));
check(new Set(replies.map((r) => r[0])).size === 3 && same(replies.map((r) => r[1]), [false, false, true]), "세 번의 말이 모두 다르고, 세 번째에만 직원을 불러야 해요.");

// ⑦ ⑧ 금액은 코드가 계산한다
const rec = receipt({
  items: [{ menu: "아메리카노", qty: 2, temp: "아이스", size: "보통" }, { menu: "바닐라라떼", qty: 1, temp: "따뜻하게", size: "큰 컵" }],
  where: "포장", done: true,
});
console.log("합계:", rec.total, "원");
check(rec.total === 3000 * 2 + (4000 + 500) * 1, "합계 = 한 개 값 × 수량의 합 (큰 컵은 +500원)이어야 해요.");
